class TestPerformance:
    """Performance characteristics under load."""

    def test_bulk_evaluation_speed(self, threshold_instance):
        """1000 evaluations should complete quickly (< 1s)."""
        import time
        start = time.perf_counter()
        for seed in range(1000):
            metrics = _generate_random_metrics(seed=seed)
            threshold_instance.evaluate(metrics)
        elapsed = time.perf_counter() - start
        assert elapsed < 1.0, f"Bulk evaluation too slow: {elapsed:.3f}s"

    def test_concurrent_safety(self, threshold_instance):
        """Concurrent evaluations should not corrupt state."""
        import threading
        errors = []

        def worker(seed):
            try:
                for i in range(100):
                    metrics = _generate_random_metrics(seed=seed * 100 + i)
                    threshold_instance.evaluate(metrics)
            except Exception as e:
                errors.append(e)

        threads = [threading.Thread(target=worker, args=(i,)) for i in range(8)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        assert not errors, f"Concurrent evaluation errors: {errors}"


